// Words whose greedy left-to-right segmentation would group letters that do
// NOT make that sound there (the 'ch' in school, the 'er' in here/there).
// Words with SOUND_FIXES seg entries are NOT listed here — fixes win first.
const SEGMENT_OVERRIDES = {
  school:   ['s', 'c', 'h', 'oo', 'l'],
  carry:    ['c', 'a', 'r', 'r', 'y'],
  warm:     ['w', 'a', 'r', 'm'],
  here:     ['h', 'e', 'r', 'e'],
  there:    ['th', 'e', 'r', 'e'],
  where:    ['wh', 'e', 'r', 'e'],
  very:     ['v', 'e', 'r', 'y'],
  every:    ['e', 'v', 'e', 'r', 'y'],
};

// Split a display word into tappable sound units, preserving original casing.
function segmentDisplay(display) {
  const lower = display.toLowerCase();
  const override = (SOUND_FIXES[lower] && SOUND_FIXES[lower].seg) || SEGMENT_OVERRIDES[lower];
  const segs = [];
  if (override) {
    let pos = 0;
    for (const o of override) { segs.push(display.slice(pos, pos + o.length)); pos += o.length; }
    return segs;
  }
  let i = 0;
  while (i < lower.length) {
    const d = DIGRAPHS.find(d => lower.startsWith(d, i));
    const len = d ? d.length : 1;
    segs.push(display.slice(i, i + len));
    i += len;
  }
  return segs;
}

const DIGIT_NAMES = {
  0: 'zero', 1: 'one', 2: 'two', 3: 'three', 4: 'four',
  5: 'five', 6: 'six', 7: 'seven', 8: 'eight', 9: 'nine',
};

// TTS fallback string for a sound unit, or null if the unit isn't speakable.
function soundFallback(key) {
  return LETTER_SOUNDS[key] || DIGRAPH_TTS[key] || TTS_EXTENDED[key] || null;
}

// Magic-e words: the vowel + final e act as a team — the e is silent, it
// makes the vowel say its name. Tapping the VOWEL plays the long team sound
// (reusing the matching long-vowel-team clip: a_e->ay, i_e->igh/eye,
// o_e->oa/oh, u_e->ue/'new' TTS, e_e->ee). The final e itself plays NO sound
// when tapped — it only flashes.
const MAGIC_E_CLIP = { a: 'ay', i: 'igh', o: 'oa', u: 'ue', e: 'ee' };

// Words spelled with a silent final 'e' but NOT pronounced with a magic e
// (short vowel + silent e like 'have'/'come', or another vowel team like
// 'here'/'shore'). Their final 'e' gets the dim silent-e colour and plays
// no sound when tapped.
const NOT_MAGIC_E = new Set(['have', 'live', 'give', 'wore', 'love', 'come', 'some', 'done', 'none', 'here', 'there', 'where', 'shore', 'store']);
const VOWEL_SET   = new Set(['a', 'e', 'i', 'o', 'u']);

// True when a segmented word has one short vowel plus a final 'e' as its own
// sound unit: CVCe or CCVCe (the e is the only other vowel letter).
function isCVCEShape(segs) {
  if (segs.length !== 4 || segs[3] !== 'e') return false;
  let vowels = 0;
  for (let i = 0; i < 3; i++) {
    if (VOWEL_SET.has(segs[i])) vowels++;
  }
  return vowels === 1;
}

// Build the sound-unit spans for a display word: one span per unit, with the
// compound units (sh, ck, ee, ue, …) tinted so the child can see which
// letters make one sound. Tap/drag handling lives on the container via
// attachSoundUnitGestures.
function buildSoundUnitSpans(display) {
  const frag = document.createDocumentFragment();
  const segs = segmentDisplay(display);
  const lower = display.toLowerCase();
  const cvce  = isCVCEShape(segs);
  const magicE  = cvce && !NOT_MAGIC_E.has(lower);
  // Silent final e: any listed word whose last unit is 'e' — not just CVCe
  // shapes ('wore'/'shore' are team + e; 'here'/'there'/'where' are shaped
  // like CVCe by their SEGMENT_OVERRIDES but are not magic-e words).
  const silentE = NOT_MAGIC_E.has(lower) && segs[segs.length - 1].toLowerCase() === 'e';
  const vowelIdx = cvce ? segs.findIndex(s => VOWEL_SET.has(s)) : -1;
  const lastIdx  = segs.length - 1;
  // Per-word fixes from the sound audit. Positional keys ('e#2') address a
  // specific occurrence of a repeated unit; plain keys are unique per word.
  const fix    = SOUND_FIXES[lower] || {};
  // silent arrives as an array of unit names; fixAt wants a lookup table
  const silentFix = Array.isArray(fix.silent)
    ? Object.fromEntries(fix.silent.map(u => [u, true])) : fix.silent;
  const counts = {};
  const nth    = [];
  segs.forEach((s, i) => {
    const k = s.toLowerCase();
    counts[k] = (counts[k] || 0) + 1;
    nth[i] = counts[k];
  });
  const fixAt = (table, key, idx) => {
    if (!table) return undefined;
    return counts[key] > 1 ? table[key + '#' + nth[idx]] : table[key];
  };
  const openFamUnits = new Set(
    (fix.fams || []).filter(fe => fe.fam === 'open-syllable').map(fe => fe.unit));
  segs.forEach((seg, idx) => {
    const span = document.createElement('span');
    span.className   = 'letter';
    span.textContent = seg;
    if (seg.length > 1) span.classList.add('alt');
    if (magicE && (idx === vowelIdx || idx === lastIdx)) {
      span.classList.add('magic-e');
      if (idx === vowelIdx) span.dataset.clip = MAGIC_E_CLIP[seg.toLowerCase()];
      else span.dataset.silent = '1';  // the final e: silent team partner
    }
    if (silentE && idx === lastIdx) {
      span.classList.add('silent-e');
      span.dataset.silent = '1';
    }
    const key = seg.toLowerCase();
    const fixClip = fixAt(fix.over, key, idx);
    if (fixClip && !span.dataset.silent) {
      span.dataset.clip = fixClip;
      // "Vowel says its name" words wear the magic-e tint the child already
      // knows from home/cake.
      if (openFamUnits.has(key)) span.classList.add('magic-e');
    }
    const spokenSound = fixAt(fix.speech, key, idx);
    if (spokenSound && !span.dataset.silent) {
      span.dataset.sound = spokenSound;
      delete span.dataset.clip;
    }
    if (fixAt(silentFix, key, idx) !== undefined && !span.dataset.silent) {
      span.classList.add('silent-e');
      span.dataset.silent = '1';
    }
    if (soundFallback(key) || DIGIT_NAMES[key] || span.dataset.clip || span.dataset.sound) span.classList.add('tappable');
    frag.appendChild(span);
  });
  return frag;
}

function triggerSoundSpan(span) {
  span.classList.remove('tapped');
  void span.offsetWidth;  // restart the flash animation
  span.classList.add('tapped');
  if (span.dataset.silent) return;  // silent letters flash but say nothing
  playLetterSound(span.dataset.clip || span.textContent, span.dataset.sound);
}

// Tap OR drag: a finger dragged across the word triggers each letter/group
// once as it is crossed (kids sound words out left-to-right this way).
// Uses elementFromPoint because touch pointers are implicitly captured by the
// pointerdown target, so pointermove would otherwise never retarget.
function attachSoundUnitGestures(container, opts = {}) {
  let tracking = false;
  let lastSpan = null;

  const spanAt = (x, y) => {
    const el   = document.elementFromPoint(x, y);
    const span = el && el.closest ? el.closest('.letter.tappable') : null;
    return span && container.contains(span) ? span : null;
  };

  const fire = (span) => {
    if (!span || span === lastSpan) return;
    lastSpan = span;
    triggerSoundSpan(span);
    opts.onTrigger?.(span);
  };

  container.addEventListener('pointerdown', (e) => {
    if (opts.guard && !opts.guard()) return;
    const span = spanAt(e.clientX, e.clientY);
    if (!span) return;
    e.preventDefault();
    tracking = true;
    lastSpan = null;
    fire(span);
  });

  container.addEventListener('pointermove', (e) => {
    if (!tracking) return;
    if (opts.guard && !opts.guard()) { tracking = false; return; }
    fire(spanAt(e.clientX, e.clientY));
  });

  const stop = () => { tracking = false; lastSpan = null; };
  container.addEventListener('pointerup', stop);
  container.addEventListener('pointercancel', stop);
}

const letterAudioCache = {};
let letterSoundPlaybackSequence = 0;

// Bump when the clips in audio/letters/ are regenerated: the service worker
// caches audio exact-URL, so a new query string forces a refetch.
const AUDIO_VERSION = 4;

function playLetterSound(seg, forceSpeak) {
  cancelRuleLessonPlayback('letter sound');
  stopLetterSoundPlayback();
  const playbackSequence = letterSoundPlaybackSequence;
  if (forceSpeak) { speak(forceSpeak, 0.8); return; }
  const key = seg.toLowerCase();
  const fallback = soundFallback(key);
  if (fallback) {
    let a = letterAudioCache[key];
    if (!a) {
      a = new Audio('./audio/letters/' + key + '.mp3?v=' + AUDIO_VERSION);
      letterAudioCache[key] = a;
    }
    try { speechSynthesis.cancel(); } catch (_) {}
    a.currentTime = 0;
    a.play().catch((e) => {
      if (playbackSequence !== letterSoundPlaybackSequence) return;
      DBG('letterAudio', key + ' failed: ' + e.name + ' — falling back to TTS');
      speak(fallback, 0.8);
    });
    return;
  }
  if (DIGIT_NAMES[key]) speak(DIGIT_NAMES[key], 0.8);
}

function stopLetterSoundPlayback() {
  letterSoundPlaybackSequence++;
  for (const audio of Object.values(letterAudioCache)) audio.pause();
}

