// ============================================================
// ACCEPTED OVERRIDES
// ============================================================
//
// Extra accepted answers discovered by auditioning on a real voice (grown-up
// tuning screen) and promoted into the canonical app. Keyed by item id; merged
// into each item's accepted list at load, so they reach BOTH fresh installs and
// devices that already have saved progress (the seed only fills missing items,
// it never touches an existing item's accepted list).
//
// To add to this: on your dev machine, audition terms in Settings → "Audition &
// edit all terms", then run rlExportAccepted() in the console (or tap Export on
// that screen) and paste the `acceptedAdditions` entries below.
// Genuine homophones and previously confirmed recognizer spellings.
// Applied on every load so existing users benefit even after the one-time
// acceptedPruned migration has already run.
const ACCEPTED_OVERRIDES = {
  'word:mat':  ['matt'],  // Spoken "mat" and the name "Matt" are identical.
  'word:are':  ['our', 'r', 'ah'],  // Chrome en-GB often returns nothing or 'our'/'r' for 'are'
};

// Returns a map of id → Set<normText> covering only the terms baked into the
// content arrays (the canonical homophones / accepted spellings).
function buildCanonicalAcceptedMap() {
  const map = {};
  for (const c of [...WORDS_CONTENT, ...WORD_COURSE.additionalWords, ...NUMBERS_CONTENT]) {
    map[c.id] = new Set(c.accepted.map(normText));
  }
  return map;
}

function applyAcceptedOverrides(items) {
  for (const [id, terms] of Object.entries(ACCEPTED_OVERRIDES)) {
    const item = items[id];
    if (!item) continue;
    for (const term of terms) {
      const n = normText(term);
      if (n && !item.accepted.some(a => normText(a) === n)) item.accepted.push(n);
    }
  }
}

// Dump accepted-term additions (vs. canonical defaults + overrides already in
// source) plus any custom items, ready to paste back into ACCEPTED_OVERRIDES /
// the content arrays. Copied to clipboard; also printed to the console.
window.rlExportAccepted = function () {
  const canon = buildCanonicalAcceptedMap();

  const acceptedAdditions = {};
  const customItems = [];

  for (const item of Object.values(stored.items)) {
    if (item.id.startsWith('custom:')) {
      customItems.push({
        id: item.id, kind: item.kind, display: item.display,
        accepted: item.accepted.map(normText), level: item.level || 1,
      });
      continue;
    }
    const base  = new Set([
      ...(canon[item.id] || []),
      ...((ACCEPTED_OVERRIDES[item.id] || []).map(normText)),
    ]);
    const extra = [];
    for (const a of item.accepted) {
      const n = normText(a);
      if (n && !base.has(n) && !extra.includes(n)) extra.push(n);
    }
    if (extra.length) acceptedAdditions[item.id] = extra;
  }

  const out  = { acceptedAdditions, customItems };
  const json = JSON.stringify(out, null, 2);
  try { console.log('%c===== ReadingLearner accepted export =====', 'font-weight:bold'); } catch (_) {}
  console.log(json);
  try { navigator.clipboard.writeText(json).then(() => console.log('(copied to clipboard)')); } catch (_) {}
  return out;
};

const PRAISE = [
  'Yes!', 'Great job!', 'You got it!', 'Well done!', 'Amazing!',
  'Wonderful!', "That's right!", 'Brilliant!', 'Super!', 'Perfect!',
  'Fantastic!', 'Lovely!',
];

// ============================================================
// STORAGE
// ============================================================

const STORAGE_KEY = 'readingLearner.v1';

const DEFAULT_SETTINGS = {
  roundSize: 10,
  wordLevel: 1,
  numberLevel: 1,
  knownStarterWordIds: [],
  voiceName: null,
  speechRate: 0.9,
};

const NUMBER_LEVEL_COUNT = 10;

function levelCountForSet(set) {
  if (set === 'words') return WORD_COURSE.levels.length;
  if (set === 'numbers') return NUMBER_LEVEL_COUNT;
  throw new Error('Unknown practice set: ' + set);
}

function makeItem(c, kind) {
  return {
    id: c.id,
    kind: kind || (c.id.startsWith('num:') ? 'number' : 'word'),
    display: c.display,
    accepted: [...c.accepted],
    level: c.level || 1,
    successStreak: 0,
    unaidedStreak: 0,
    silentCorrect: 0,
    masteryConfirmationCount: 0,
    flawlessConfirmationCount: 0,
    totalCorrect: 0,
    totalAttempts: 0,
    decoded: false,   // silver: sounded out with letter taps, no Hear it
    mastered: false,  // gold: two first-attempt Yeses with at most one sound tap
    flawless: false,  // purple: two first-attempt Yeses without sound taps
    lastSeenRound: null,
    lastRecapRound: null,  // last round number this item was surfaced as a recap
    lastResult: null,
    auditionConfs: [],
  };
}

function freshState() {
  const items = {};
  for (const c of NUMBERS_CONTENT) items[c.id] = makeItem(c, 'number');
  for (const c of [...WORDS_CONTENT, ...WORD_COURSE.additionalWords]) items[c.id] = makeItem(c, 'word');
  applyAcceptedOverrides(items);
  return {
    version: 1,
    createdAt: new Date().toISOString(),
    settings: { ...DEFAULT_SETTINGS, knownStarterWordIds: [] },
    items,
    rounds: [],
    rulesHeard: {},
    acceptedPruned: true,
    cvcLevels: true,
    forwardLevels: true,
    wordCourse: createWordCourseProgress(),
    wordCourseHistory: [],
  };
}

let stored = null;

function loadStored() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) { stored = freshState(); saveStored(); return; }
    const parsed = JSON.parse(raw);
    if (!parsed || parsed.version !== 1) throw new Error('Unexpected storage version.');
    const fresh = freshState();
    for (const id of Object.keys(fresh.items)) {
      if (!parsed.items[id]) parsed.items[id] = fresh.items[id];
    }
    // Parked and historical words retain their original progress records.
    for (const k of Object.keys(DEFAULT_SETTINGS)) {
      if (parsed.settings[k] === undefined) parsed.settings[k] = Array.isArray(DEFAULT_SETTINGS[k]) ? [...DEFAULT_SETTINGS[k]] : DEFAULT_SETTINGS[k];
    }
    delete parsed.settings.retryCap;
    for (const item of Object.values(parsed.items)) {
      if (!item.kind) item.kind = item.id.startsWith('num:') ? 'number' : 'word';
      if (item.level === undefined) item.level = 1;
      if (item.unaidedStreak === undefined) item.unaidedStreak = item.silentCorrect || 0;
      if (item.decoded === undefined)  item.decoded  = false;
      if (item.flawless === undefined) item.flawless = false;
      // Historic recognizer scores are not self-confirmations. Earned trophies
      // remain permanent, but these new counts start at zero on older saves.
      if (item.masteryConfirmationCount === undefined) item.masteryConfirmationCount = 0;
      if (item.flawlessConfirmationCount === undefined) item.flawlessConfirmationCount = 0;
      for (const countName of ['masteryConfirmationCount', 'flawlessConfirmationCount']) {
        if (!Number.isInteger(item[countName]) || item[countName] < 0 || item[countName] > 2) {
          throw new Error('Invalid confirmation count for ' + item.display + '.');
        }
      }
      if (!item.auditionConfs) item.auditionConfs = [];
    }
    applyAcceptedOverrides(parsed.items);

    // One-time migration: strip accepted terms accumulated by hear-then-learn
    // back to canonical homophones only. Grown-up manual additions via the
    // tuning screen survive only if they match a canonical entry.
    if (!parsed.acceptedPruned) {
      const canon = buildCanonicalAcceptedMap();
      for (const [id, item] of Object.entries(parsed.items)) {
        if (id.startsWith('custom:')) continue;
        const allowed = canon[id];
        if (allowed) item.accepted = item.accepted.filter(a => allowed.has(normText(a)));
      }
      parsed.acceptedPruned = true;
    }

    // Retain the older number-course advancement. Word placement now has
    // its own migration and must not inherit old numeric level meanings.
    if (!parsed.forwardLevels) {
      let level = parsed.settings.numberLevel;
      while (level < NUMBER_LEVEL_COUNT) {
        const items = Object.values(parsed.items).filter(item => item.kind === 'number' && item.level === level);
        if (!items.length || !items.every(item => item.mastered)) break;
        level++;
      }
      parsed.settings.numberLevel = level;
      parsed.forwardLevels = true;
    }
    parsed.rulesHeard = parsed.rulesHeard || {};
    migrateWordCourseProgress(parsed);

    stored = parsed;
    saveStored();
  } catch (e) {
    showStorageError(e.message);
  }
}

function saveStored() {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(stored));
  } catch (e) {
    console.error('Save failed:', e);
  }
}

function showStorageError(msg) {
  document.body.innerHTML = `
    <div style="position:fixed;inset:0;background:#0f0c29;color:#fff;display:flex;
      flex-direction:column;align-items:center;justify-content:center;padding:2rem;
      gap:1.5rem;font-family:sans-serif;text-align:center;max-width:480px;margin:auto;">
      <h2 style="font-size:1.5rem">Something went wrong</h2>
      <p style="color:#a0a0c0;font-size:0.95rem">${msg}</p>
      <button
        onclick="localStorage.removeItem('${STORAGE_KEY}');location.reload()"
        style="padding:1rem 2rem;background:#e94560;color:white;border:none;
          border-radius:1rem;font-size:1rem;cursor:pointer;font-family:sans-serif;font-weight:700;">
        Reset progress &amp; reload
      </button>
    </div>`;
}

// ============================================================
// SPEECH SYNTHESIS
// ============================================================

let levelImages = {};

async function loadImageManifest() {
  const resp = await fetch('./images/manifest.json');
  if (!resp.ok) throw new Error('Number picture manifest could not load.');
  const manifest = await resp.json();
  if (!manifest.numbers || typeof manifest.numbers !== 'object') throw new Error('Number picture manifest is invalid.');
  levelImages = manifest;
}

let voices = [];

function loadVoices() {
  voices = window.speechSynthesis ? speechSynthesis.getVoices() : [];
  populateVoiceSelect();
}

if (window.speechSynthesis) {
  if (speechSynthesis.onvoiceschanged !== undefined) {
    speechSynthesis.onvoiceschanged = loadVoices;
  }
  loadVoices();
}

function getVoice() {
  if (stored?.settings?.voiceName) {
    const v = voices.find(v => v.name === stored.settings.voiceName);
    if (v) return v;
  }
  const en = voices.filter(v => v.lang.startsWith('en'));
  // Prefer online/neural voices — much higher quality (e.g. Google UK English Female on Chrome)
  const onlineGB = en.find(v => v.lang === 'en-GB' && !v.localService);
  if (onlineGB) return onlineGB;
  const onlineEN = en.find(v => !v.localService);
  if (onlineEN) return onlineEN;
  const localGBFemale = en.find(v => v.lang === 'en-GB' && /female|serena|kate|emily|fiona|amy/i.test(v.name));
  if (localGBFemale) return localGBFemale;
  const localGB = en.find(v => v.lang === 'en-GB');
  if (localGB) return localGB;
  return en[0] || voices[0] || null;
}

let currentUtterance = null;

function speak(text, rate, onEnd, playbackEvents = {}) {
  if (activeRuleLessonPlayback && playbackEvents.ruleLessonPlayback !== activeRuleLessonPlayback) {
    cancelRuleLessonPlayback('another spoken help', false);
  }
  const snippet = text.length > 24 ? text.slice(0, 24) + '…' : text;
  if (!window.speechSynthesis) { DBG('speak', 'NO speechSynthesis'); onEnd?.('unavailable'); return; }
  speechSynthesis.cancel();
  const utt = new SpeechSynthesisUtterance(text);
  currentUtterance = utt;
  const v = getVoice();
  utt.voice  = v;
  utt.rate   = rate ?? stored?.settings?.speechRate ?? 0.9;
  utt.pitch  = 1.1;
  utt.volume = 1;
  DBG('speak.start', { text: snippet, voice: v ? v.name : 'NONE' });

  let done = false;
  const finish = (how) => {
    if (done) return;
    done = true;
    clearTimeout(watchdog);
    if (how === 'WATCHDOG' && currentUtterance === utt) speechSynthesis.cancel();
    if (currentUtterance === utt) currentUtterance = null;
    DBG('speak.end', { text: snippet, how });
    onEnd?.(how);
  };
  utt.onend   = () => finish('onend');
  utt.onerror = (ev) => finish('onerror:' + (ev.error || '?'));
  utt.onstart = (event) => {
    if (!done && currentUtterance === utt) playbackEvents.onStart?.(event, utt.rate);
  };
  utt.onboundary = (event) => {
    if (!done && currentUtterance === utt) playbackEvents.onBoundary?.(event);
  };
  const watchdog = setTimeout(() => finish('WATCHDOG'), Math.max(4000, text.length * 100 + 2000));

  speechSynthesis.speak(utt);
}

const speakWord = (w, cb, playbackEvents) => speak(w, stored.settings.speechRate, cb, playbackEvents);

// ============================================================
// MICROPHONE CAPTURE AND TUNING RECOGNITION
// ============================================================

let voskModel       = null;
let micStream       = null;
let audioCtx        = null;
let scriptProc      = null;
let voskReady       = false;
let tuningModelOpeningPromise = null;
let microphoneOpeningPromise = null;
let microphoneStreamGeneration = 0;
let spokenAttemptGeneration = 0;

let capturedMicrophoneSampleCount = 0;
let maxListenTimer    = null;
let unblockTimer      = null;
let sessionMicBlocked = false;

// 'waiting' | 'ready' | 'warming' | 'listening' | 'confirming' | 'repeat-ready'
let micState = 'waiting';

// ── Audition (grown-up tuning screen) — open-vocabulary recognizer ──
let auditionRecognizer = null;
let auditionState      = 'idle';   // 'idle' | 'listening' | 'evaluating'
let auditionRowId      = null;
let auditionHeard      = [];
let auditionConfScores = [];   // mean Vosk conf per result event this session
let auditionEvaluated  = false;
let auditionMaxTimer   = null;
let auditionSettleTimer = null;
let auditionAttemptGeneration = 0;

async function initVosk() {
  if (voskReady) return;
  if (tuningModelOpeningPromise) return tuningModelOpeningPromise;
  if (!window.Vosk) throw new Error('The bundled speech engine did not load.');
  tuningModelOpeningPromise = (async () => {
    DBG('vosk', 'loading model…');
    const modelUrl = new URL('./model.tar.gz', window.location.href).href;
    voskModel = await Vosk.createModel(modelUrl);
    voskModel.setLogLevel(-1);
    voskReady = true;
    DBG('vosk', 'model ready');
  })();
  try {
    await tuningModelOpeningPromise;
  } catch (e) {
    DBG('vosk', 'load FAILED: ' + String(e));
    throw e;
  } finally {
    tuningModelOpeningPromise = null;
  }
}

// Open-vocabulary recognizer (no grammar) used only on the tuning screen, so
// the grown-up hears what Vosk detects. Practice uses the child's self-check.
function createAuditionRecognizer() {
  if (auditionRecognizer) { try { auditionRecognizer.remove(); } catch (_) {} auditionRecognizer = null; }
  if (!voskReady) return;
  auditionRecognizer = new voskModel.KaldiRecognizer(16000);
  const tuningRecognizer = auditionRecognizer;

  const collectTranscript = (msg) => {
    if (tuningRecognizer !== auditionRecognizer) return;
    const text = (msg.result.text || '').trim();
    DBG('audition.result', { text, auditionState });
    if (auditionState !== 'listening' && auditionState !== 'evaluating') return;
    if (text && text !== '[unk]' && !auditionHeard.includes(text)) auditionHeard.push(text);
    const words = (msg.result.result || []).filter(w => w.conf != null);
    if (words.length) {
      auditionConfScores.push(words.reduce((s, w) => s + w.conf, 0) / words.length);
    }
  };
  auditionRecognizer.on('result', collectTranscript);
  auditionRecognizer.on('finalresult', msg => {
    if (tuningRecognizer !== auditionRecognizer || auditionState !== 'evaluating' || auditionEvaluated) return;
    collectTranscript(msg);
    finishAudition();
  });
  auditionRecognizer.on('error', msg => {
    if (tuningRecognizer === auditionRecognizer) onSpeechEngineError(msg.error);
  });
}

function openMicStream() {
  if (micStream) return Promise.resolve(true);
  if (microphoneOpeningPromise) return microphoneOpeningPromise;
  const openingGeneration = microphoneStreamGeneration;
  const openingPromise = (async () => {
    let openedStream = null;
    let openedContext = null;
    try {
      openedStream = await navigator.mediaDevices.getUserMedia({
        audio: { channelCount: 1, echoCancellation: true, noiseSuppression: true },
        video: false,
      });
      if (openingGeneration !== microphoneStreamGeneration) {
        openedStream.getTracks().forEach(track => track.stop());
        return false;
      }
      openedContext = new AudioContext({ sampleRate: 16000 });
      if (openedContext.sampleRate !== 16000) {
        throw new Error('The microphone must run at the speech engine\'s 16 kHz sample rate.');
      }
      const source = openedContext.createMediaStreamSource(openedStream);
      const processor = openedContext.createScriptProcessor(4096, 1, 1);
      processor.onaudioprocess = event => {
        if (openingGeneration !== microphoneStreamGeneration) return;
        try {
          if (auditionState === 'listening' && auditionRecognizer) {
            auditionRecognizer.acceptWaveform(event.inputBuffer);
          } else if (micState === 'listening') {
            if (!Number.isInteger(event.inputBuffer.length) || event.inputBuffer.length <= 0) {
              throw new Error('The microphone did not provide audio samples.');
            }
            capturedMicrophoneSampleCount += event.inputBuffer.length;
          }
        } catch (error) {
          if (auditionState !== 'idle') onSpeechEngineError(error.message);
          else recoverSpokenCapture(error.message);
        }
      };
      source.connect(processor);
      processor.connect(openedContext.destination);
      micStream = openedStream;
      audioCtx = openedContext;
      scriptProc = processor;
      DBG('mic', 'open sampleRate=' + audioCtx.sampleRate);
      return true;
    } catch (error) {
      if (openedStream) openedStream.getTracks().forEach(track => track.stop());
      if (openedContext) await openedContext.close();
      if (openingGeneration !== microphoneStreamGeneration) return false;
      DBG('mic', 'capture setup failed: ' + error.message);
      if (error.name === 'NotAllowedError' || error.name === 'PermissionDeniedError') onMicDenied();
      else onMicUnavailable();
      return false;
    }
  })().finally(() => {
    if (microphoneOpeningPromise === openingPromise) microphoneOpeningPromise = null;
  });
  microphoneOpeningPromise = openingPromise;
  return openingPromise;
}

function closeMicStream() {
  microphoneStreamGeneration++;
  spokenAttemptGeneration++;
  auditionAttemptGeneration++;
  microphoneOpeningPromise = null;
  clearTimeout(maxListenTimer);
  clearTimeout(auditionMaxTimer);
  clearTimeout(auditionSettleTimer);
  cancelUnblock();
  capturedMicrophoneSampleCount = 0;
  if (scriptProc) { try { scriptProc.disconnect(); } catch (_) {} scriptProc = null; }
  if (audioCtx)   { try { audioCtx.close(); } catch (_) {} audioCtx = null; }
  if (micStream)  { micStream.getTracks().forEach(t => t.stop()); micStream = null; }
  if (auditionRecognizer) { try { auditionRecognizer.remove(); } catch (_) {} auditionRecognizer = null; }
  DBG('mic', 'closed');
}

async function startListening() {
  const encounter = gs.spokenWordEncounter;
  if (!encounter || encounter.committed) return;
  if (micState === 'confirming' && encounter.phase === 'confirming') {
    encounter.phase = 'repeat-ready';
    clearTimeout(encounter.answerChoiceActivationTimer);
    encounter.answerChoiceActivationTimer = null;
    speechSynthesis.cancel();
  }
  const helpedRepeat = encounter.phase === 'repeat-ready';
  if (!helpedRepeat && encounter.phase !== 'first-ready') return;
  DBG('startListening', { sessionMicBlocked, helpedRepeat });
  if (sessionMicBlocked) { onMicDenied(); return; }
  const attemptGeneration = ++spokenAttemptGeneration;
  setMicState('warming');
  if (!await openMicStream()) return;
  if (attemptGeneration !== spokenAttemptGeneration || gs.spokenWordEncounter !== encounter) return;
  try {
    await audioCtx.resume();
  } catch (error) {
    if (attemptGeneration !== spokenAttemptGeneration || gs.spokenWordEncounter !== encounter) return;
    DBG('mic', 'audio capture could not resume: ' + error.message);
    onMicUnavailable();
    return;
  }
  if (attemptGeneration !== spokenAttemptGeneration || gs.spokenWordEncounter !== encounter) return;
  if (!helpedRepeat) {
    encounter.firstAttemptAssistance = Object.freeze({ hearPressed: gs.hearPressed, letterTaps: gs.letterTaps });
  }
  encounter.phase = helpedRepeat ? 'repeat-recording' : 'first-recording';
  capturedMicrophoneSampleCount = 0;
  setMicState('listening');
  maxListenTimer = setTimeout(() => {
    if (attemptGeneration === spokenAttemptGeneration) finishSpokenAttempt();
  }, 10000);
}

function finishSpokenAttempt() {
  DBG('finishSpokenAttempt', { micState, capturedMicrophoneSampleCount });
  if (micState !== 'listening') return;
  clearTimeout(maxListenTimer);
  const encounter = gs.spokenWordEncounter;
  if (!encounter || encounter.committed) return;
  const healthyCapture = audioCtx?.state === 'running' && micStream &&
    micStream.getTracks().every(track => track.readyState === 'live') && capturedMicrophoneSampleCount > 0;
  if (!healthyCapture) {
    recoverSpokenCapture('That recording did not finish. Please record it again.');
    return;
  }
  const helpedRepeat = encounter.phase === 'repeat-recording';
  if (!helpedRepeat && encounter.phase !== 'first-recording') throw new Error('A recording must belong to the current word.');
  const recordingGeneration = ++spokenAttemptGeneration;
  const recordedPhase = helpedRepeat ? 'repeat-recorded' : 'first-recorded';
  encounter.phase = recordedPhase;
  setMicState('waiting');
  setTimeout(() => {
    if (gs.spokenWordEncounter !== encounter || spokenAttemptGeneration !== recordingGeneration ||
        encounter.committed || encounter.phase !== recordedPhase) return;
    if (helpedRepeat) commitSelfCheckedAnswer('helped-repeat');
    else askSpokenSelfCheck(encounter);
  }, 500);
}

// Speech engines may finish their utterance after a trailing silence. Estimate
// the audible answer length; this changes button timing, never speech playback.
function estimateAnswerSpeechDurationMs(display, speechRate) {
  if (!Number.isFinite(speechRate) || speechRate <= 0) throw new Error('Answer speech needs a positive speaking rate.');
  const spokenAnswer = /^\d+$/.test(display) ? numberToWords(Number(display)) : display;
  const spokenWords = spokenAnswer.toLowerCase().match(/[a-z]+/g);
  if (!spokenWords?.length) throw new Error('The spoken answer needs words for its timing estimate.');
  let syllableCount = 0;
  let consonantCount = 0;
  for (const word of spokenWords) {
    const syllableSpelling = word.length > 3 && !/[^aeiouy]le$/.test(word) ? word.replace(/e$/, '') : word;
    syllableCount += Math.max(1, (syllableSpelling.match(/[aeiouy]+/g) || []).length);
    consonantCount += (word.match(/[^aeiouy]/g) || []).length;
  }
  return Math.round((260 + 180 * (syllableCount - 1) + 30 * consonantCount + 40 * (spokenWords.length - 1)) / speechRate);
}

function askSpokenSelfCheck(encounter) {
  if (gs.spokenWordEncounter !== encounter || encounter.committed) return;
  clearTimeout(encounter.answerChoiceActivationTimer);
  encounter.answerChoiceActivationTimer = null;
  const answerPlaybackSequence = ++encounter.answerPlaybackSequence;
  const answerDisplay = gs.currentItem.display;
  let answerSpeechStarted = false;
  const answerPlaybackIsCurrent = () => gs.spokenWordEncounter === encounter && !encounter.committed &&
    encounter.answerPlaybackSequence === answerPlaybackSequence &&
    (encounter.phase === 'answer' || encounter.phase === 'confirming');
  const enableAnswerChoices = () => {
    if (!answerPlaybackIsCurrent() || encounter.phase !== 'answer') return;
    encounter.phase = 'confirming';
    setMicState('confirming');
  };
  encounter.phase = 'answer';
  const question = `${answerDisplay}. Got it?`;
  document.getElementById('self-check-question').textContent = question;
  setMicState('waiting');
  speakWord(answerDisplay, how => {
    if (!answerPlaybackIsCurrent()) return;
    clearTimeout(encounter.answerChoiceActivationTimer);
    encounter.answerChoiceActivationTimer = null;
    if (how !== 'onend') {
      encounter.phase = 'answer-error';
      document.getElementById('self-check-question').textContent = 'The word could not play. Check sound, then tap Hear it to try again.';
      setMicState('answer-error');
      return;
    }
    enableAnswerChoices();
    speak('Got it?', stored.settings.speechRate);
  }, {
    onStart: (_event, speechRate) => {
      if (!answerPlaybackIsCurrent() || encounter.phase !== 'answer' || answerSpeechStarted) return;
      answerSpeechStarted = true;
      const estimatedDurationMs = estimateAnswerSpeechDurationMs(answerDisplay, speechRate);
      DBG('answer buttons estimated ending', { answer: answerDisplay, durationMs: estimatedDurationMs, speechRate });
      encounter.answerChoiceActivationTimer = setTimeout(() => {
        if (!answerPlaybackIsCurrent() || encounter.phase !== 'answer') return;
        encounter.answerChoiceActivationTimer = null;
        enableAnswerChoices();
      }, estimatedDurationMs);
    },
    onBoundary: event => {
      // charLength describes text still to be spoken, not the word's ending.
      if (!answerPlaybackIsCurrent() || !Number.isInteger(event.charIndex) || event.charIndex < answerDisplay.length) return;
      clearTimeout(encounter.answerChoiceActivationTimer);
      encounter.answerChoiceActivationTimer = null;
      enableAnswerChoices();
    },
  });
}

// ============================================================
// ANSWER MATCHING
// ============================================================

function normText(s) {
  return s.toLowerCase().replace(/[^\w\s]/g, '').replace(/\s+/g, ' ').trim();
}

// True when `run` appears as a consecutive whole-token sequence in `tokens`.
function containsTokenRun(tokens, run) {
  outer:
  for (let i = 0; i + run.length <= tokens.length; i++) {
    for (let j = 0; j < run.length; j++) {
      if (tokens[i + j] !== run[j]) continue outer;
    }
    return true;
  }
  return false;
}

function matchAnswer(transcripts, item) {
  if (!transcripts?.length) return false;
  const acceptedRuns = item.accepted
    .map(a => normText(a).split(' ').filter(Boolean))
    .filter(r => r.length);
  for (const raw of transcripts) {
    // normText turns "[unk]" into "unk"; drop those filler tokens so a
    // transcript like "[unk] cat [unk]" still matches "cat".
    const tokens = normText(raw).split(' ').filter(t => t && t !== 'unk');
    if (!tokens.length) continue;
    for (const run of acceptedRuns) {
      if (containsTokenRun(tokens, run)) return true;
    }
  }
  return false;
}

// Single mutation path for accepted terms (grown-up tuning screen only).
// Returns true if added.
function addAcceptedTerm(item, rawTerm) {
  const term = normText(rawTerm);
  if (!term || term === '[unk]') return false;
  if (item.accepted.some(a => normText(a) === term)) return false;
  item.accepted.push(term);
  saveStored();
  DBG('addAcceptedTerm', { id: item.id, term });
  return true;
}

// ============================================================
// AUDITION (grown-up tuning)
// ============================================================

async function armAudition(itemId) {
  DBG('armAudition', { itemId, auditionState });
  if (auditionState !== 'idle') return;
  if (sessionMicBlocked) { setRowResult(itemId, 'miss', 'microphone blocked'); return; }
  if (!voskReady) {
    setRowResult(itemId, 'miss', 'speech engine unavailable');
    return;
  }
  const attemptGeneration = ++auditionAttemptGeneration;
  auditionRowId      = itemId;
  auditionState = 'warming';
  setRowListening(itemId, true);
  if (!await openMicStream()) {
    if (attemptGeneration !== auditionAttemptGeneration) return;
    auditionState = 'idle';
    auditionRowId = null;
    setRowListening(itemId, false);
    setRowResult(itemId, 'miss', 'microphone unavailable');
    return;
  }
  if (attemptGeneration !== auditionAttemptGeneration) return;
  try {
    await audioCtx.resume();
  } catch (error) {
    if (attemptGeneration !== auditionAttemptGeneration) return;
    auditionState = 'idle';
    auditionRowId = null;
    setRowListening(itemId, false);
    setRowResult(itemId, 'miss', 'microphone could not start');
    return;
  }
  if (attemptGeneration !== auditionAttemptGeneration) return;
  try {
    createAuditionRecognizer();
  } catch (error) {
    onSpeechEngineError(error.message);
    return;
  }
  auditionHeard      = [];
  auditionConfScores = [];
  auditionEvaluated  = false;
  auditionState     = 'listening';
  auditionMaxTimer  = setTimeout(() => {
    if (attemptGeneration === auditionAttemptGeneration) stopAudition();
  }, 6000);
}

function stopAudition() {
  if (auditionState === 'warming') {
    auditionAttemptGeneration++;
    auditionState = 'idle';
    setRowListening(auditionRowId, false);
    auditionRowId = null;
    return;
  }
  if (auditionState !== 'listening') return;
  clearTimeout(auditionMaxTimer);
  auditionState = 'evaluating';
  const attemptGeneration = auditionAttemptGeneration;
  auditionSettleTimer = setTimeout(() => {
    if (attemptGeneration === auditionAttemptGeneration) onSpeechEngineError('The tuning recording did not finish processing.');
  }, 10000);
  try { auditionRecognizer.retrieveFinalResult(); }
  catch (error) { onSpeechEngineError(error.message); }
}

function finishAudition() {
  if (auditionEvaluated) return;
  if (auditionState !== 'evaluating' && auditionState !== 'listening') return;
  auditionEvaluated = true;
  clearTimeout(auditionSettleTimer);
  clearTimeout(auditionMaxTimer);

  const id   = auditionRowId;
  const item = stored.items[id];
  auditionState = 'idle';
  auditionRowId = null;
  setRowListening(id, false);
  if (!item) return;

  const heard   = [...auditionHeard];
  const best    = heard.find(t => t && t !== '[unk]') || '';
  const matched = matchAnswer(heard, item);

  let sessionConf = null;
  if (auditionConfScores.length) {
    sessionConf = auditionConfScores.reduce((s, c) => s + c, 0) / auditionConfScores.length;
    item.auditionConfs.push(Math.round(sessionConf * 100) / 100);
    if (item.auditionConfs.length > 20) item.auditionConfs.splice(0, item.auditionConfs.length - 20);
    saveStored();
  }

  DBG('audition.judge', { id, best, matched, sessionConf });
  renderAuditionResult(id, best, matched, item, sessionConf);
}

// ============================================================
// ROUND BUILDING
// ============================================================

function shuffle(arr) {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.random() * (i + 1) | 0;
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

let roundNumber = 0;

const kindForSet = (set) => (set === 'numbers' ? 'number' : 'word');

// Words the child will actually meet: rule-breakers (SOUND_AUDIT.md) are
// parked until the rules are solid; their stored progress is kept.
function isPracticeEligible(item) {
  return item.kind === 'number' || !!wordFocusLevelForItem(item) || WORD_COURSE.startingWordIds.includes(item.id);
}



function needsMorePractice(item) {
  return item.lastResult === 'helped' || item.lastResult === 'miss';
}

function buildRound(set, level) {
  roundNumber++;
  if (set === 'words') return buildWordRound(level);
  if (set !== 'numbers') throw new Error('Unknown practice set.');
  const levelItems = Object.values(stored.items).filter(item => item.kind === 'number' && item.level === level);
  return { encounters: buildNumberRound(levelItems).map(item => ({ item, role: 'practice' })), ruleFocusId: null, ruleIds: [] };
}

function buildNumberRound(levelItems) {
  const unmastered = levelItems.filter(i => !i.mastered);
  const size = Math.min(stored.settings.roundSize, levelItems.length);

  const needsRepeat = shuffle(unmastered.filter(needsMorePractice));
  const newItems = shuffle(unmastered.filter(i => i.totalAttempts === 0));
  const rest     = shuffle(unmastered.filter(i => i.totalAttempts > 0 && !needsMorePractice(i)));
  const round    = [...needsRepeat, ...newItems, ...rest].slice(0, size);

  // Top the round up with already-mastered words from the same level so a
  // round is always full-size; they get a "you know this one" reminder when
  // shown, and mastery is never revoked however they go.
  if (round.length < size) {
    for (const item of shuffle(levelItems.filter(i => i.mastered))) {
      if (round.length >= size) break;
      round.push(item);
    }
  }
  return shuffle(round);
}

// Word rounds are assembled from the active course in word-practice.js.

// One "recap" word per session, drawn from levels the child has already
// beaten (i.e. mastered items on earlier levels). Rotation is FIFO over
// lastRecapRound so every previous word gets its turn; null while no earlier
// level has been cleared yet (e.g. Level 1).
function pickRecapItem(kind, level) {
  const eligible = Object.values(stored.items).filter(
    i => i.kind === kind && i.level < level && i.mastered && isPracticeEligible(i)
  );
  if (!eligible.length) return null;
  const oldest = Math.min(...eligible.map(i => i.lastRecapRound || 0));
  const candidates = eligible.filter(i => (i.lastRecapRound || 0) === oldest);
  const pick = candidates[Math.random() * candidates.length | 0];
  pick.lastRecapRound = roundNumber;
  saveStored();
  return pick;
}

// ============================================================
// GAME STATE
// ============================================================

const gs = {
  currentSet:          null,
  currentLevel:        1,
  queue:               [],
  originalSize:        0,
  completedCount:      0,
  roundCorrect:        0,
  roundSilentCorrect:  0,
  currentItem:         null,
  currentEncounterRole: null,
  spokenWordEncounter: null,
  awaitingResult:      false,
  recapId:             null,
  hearPressed:         false,
  letterTaps:          0,
  newTrophies:         0,
  ruleFocusId:         null,    // the one focus taught in this word round
  ruleIds:            [],      // ids of the rule-block items
  ruleMissed:         false,   // any miss in the rule block cancels the rule praise
};
let spokenWordEncounterSequence = 0;

function startRound(set, level) {
  let built;
  try { built = buildRound(set, level); }
  catch (error) {
    if (error.code !== 'known_word_bank_required') throw error;
    openGrownUp();
    document.getElementById('s-familiar-word-status').textContent = error.message;
    speak('A grown-up needs to choose a word you already read.', 0.9);
    return;
  }
  gs.currentSet          = set;
  gs.currentLevel        = level;
  gs.queue               = [...built.encounters];
  gs.originalSize        = built.encounters.length;
  gs.completedCount      = 0;
  gs.roundCorrect        = 0;
  gs.roundSilentCorrect  = 0;
  gs.currentItem         = null;
  cancelWordEncounter();
  gs.awaitingResult      = false;
  gs.recapId             = null;
  gs.hearPressed         = false;

  // Number rounds retain one feedback-only recap number.
  // Feedback-only: it takes no slot (originalSize excludes it) and never
  // counts toward round stats or per-item progress.
  const recap = set === 'numbers' ? pickRecapItem('number', level) : null;
  gs.recapId = recap ? recap.id : null;
  if (recap) gs.queue.splice(Math.floor(Math.random() * gs.queue.length), 0, { item: recap, role: 'recap' });
  gs.letterTaps          = 0;
  gs.newTrophies         = 0;
  gs.ruleFocusId         = built.ruleFocusId;
  gs.ruleIds             = built.ruleIds;
  gs.ruleMissed          = false;
  saveStored();

  setLevelBackground(level, set);
  showScreen('practice');
  openMicStream();

  const roundEncounterSequence = spokenWordEncounterSequence;
  const instructions = stored.selfCheckInstructionsHeard ? '' :
    ' Say the word. Then tap Yes if you got it, or use the microphone to say it again.';
  speak(`Level ${level}!${instructions}`, 1.1, how => {
    if (roundEncounterSequence !== spokenWordEncounterSequence) return;
    if (how === 'onend') {
      stored.selfCheckInstructionsHeard = true;
      saveStored();
    }
    nextItem();
  });
}

function nextItem() {
  if (gs.queue.length === 0) { endRound(); return; }
  const queuedEncounter = gs.queue.shift();
  gs.currentItem = queuedEncounter.item;
  gs.currentEncounterRole = queuedEncounter.role;
  beginWordEncounter(gs.currentItem);
  gs.hearPressed        = false;
  gs.currentItem.lastSeenRound = roundNumber;
  gs.awaitingResult = false;
  presentItem(gs.currentItem);
}

function presentItem(item) {
  renderDots();

  const el  = document.getElementById('word-display');
  const len = item.display.length;
  el.style.fontSize =
    len <= 2  ? 'clamp(6rem, 25vmin, 14rem)' :
    len <= 4  ? 'clamp(5rem, 20vmin, 10rem)' :
    len <= 7  ? 'clamp(4rem, 15vmin,  8rem)' :
                'clamp(3rem, 11vmin,  5.5rem)';
  const isRecap = item.id === gs.recapId;
  el.className = 'word-display'
    + (item.kind === 'number' ? ' number-display' : '')
    + (isRecap ? ' recap' : '');

  // The word is split into sound units — single letters and compound sounds
  // like "sh"/"ee"/"igh". Tapping or dragging across them flashes each group
  // and plays its isolated phonetic sound, so the child can sound the word out.
  el.innerHTML = '';
  el.appendChild(buildSoundUnitSpans(item.display));
  gs.letterTaps = 0;
  renderTrophyRow(item);
  renderRuleChips(item);

  renderConfirmationProgress(item);
  DBG('presentItem', { id: item.id });
  setMicState('ready');
  const encounter = gs.spokenWordEncounter;
  const speakGuidance = (line, rate, completed) => {
    setMicState('waiting');
    speak(line, rate, how => {
      if (gs.spokenWordEncounter !== encounter || encounter.phase !== 'first-ready') return;
      if (how === 'onend') completed?.();
      setMicState('ready');
    });
  };

  document.getElementById('recap-banner').classList.toggle('hidden', !isRecap);

  // Recap numbers get the recap announcement; familiar mastered words (same
  // level) get a gentle spoken reminder. The FIRST time the child meets a
  // current focus, its declared lesson is spoken once — the chip under the word
  // is the standing, always-tappable version.
  if (isRecap) {
    speakGuidance('Recap! You learned this one before.', 1.0);
  } else {
    const focus = gs.currentSet === 'words' && gs.currentEncounterRole === 'focus' ? wordCourseLevel(gs.currentLevel) : null;
    if (focus && !stored.wordCourse.ruleLessonsHeard[focus.id]) {
      startRuleLessonPlayback(focus.id, item);
    } else if (item.mastered) {
      speakGuidance('You know this one!', 1.0);
    }
  }
}

function ruleLessonFor(focusId, display) {
  const focus = WORD_COURSE.levels.find(level => level.id === focusId);
  if (!focus || !focus.focusWords.includes(display.toLowerCase())) throw new Error('The word is outside this rule focus.');
  return focus.rulePlaybackSteps.map(step => ({ ...step }));
}

let ruleLessonPlaybackSequence = 0;
let activeRuleLessonPlayback = null;

function cancelRuleLessonPlayback(reason, releaseMicrophone = true) {
  const playback = activeRuleLessonPlayback;
  if (!playback) return;
  activeRuleLessonPlayback = null;
  ruleLessonPlaybackSequence++;
  clearTimeout(playback.soundDeadlineTimer);
  clearTimeout(playback.speechPauseTimer);
  if (playback.audio) {
    playback.audio.onended = null;
    playback.audio.onerror = null;
    playback.audio.pause();
  }
  try { speechSynthesis.cancel(); } catch (_) {}
  DBG('rule lesson cancelled', { focusId:playback.focusId, reason });
  if (releaseMicrophone && gs.spokenWordEncounter === playback.encounter && playback.encounter.phase === 'first-ready') setMicState('ready');
}

function startRuleLessonPlayback(focusId, item) {
  const encounter = gs.spokenWordEncounter;
  if (!encounter || encounter.phase !== 'first-ready' || gs.currentItem !== item) return;
  cancelRuleLessonPlayback('rule replay');
  stopLetterSoundPlayback();
  const steps = ruleLessonFor(focusId, item.display);
  const playback = {
    sequence:++ruleLessonPlaybackSequence, encounter, focusId,
    stepIndex:0, audio:null, soundDeadlineTimer:null, speechPauseTimer:null,
  };
  activeRuleLessonPlayback = playback;
  setMicState('waiting');
  const ownsLesson = () => activeRuleLessonPlayback === playback &&
    ruleLessonPlaybackSequence === playback.sequence &&
    gs.spokenWordEncounter === encounter && encounter.phase === 'first-ready' && gs.currentItem === item;
  const failLesson = message => {
    if (!ownsLesson()) return;
    cancelRuleLessonPlayback('playback failed');
    document.getElementById('mic-status').textContent = message + ' Tap the rule to try again.';
    DBG('rule lesson failed', { focusId, message });
  };
  const playNextStep = () => {
    if (!ownsLesson()) return;
    clearTimeout(playback.soundDeadlineTimer);
    playback.soundDeadlineTimer = null;
    clearTimeout(playback.speechPauseTimer);
    playback.speechPauseTimer = null;
    if (playback.audio) {
      playback.audio.onended = null;
      playback.audio.onerror = null;
      playback.audio = null;
    }
    if (playback.stepIndex === steps.length) {
      activeRuleLessonPlayback = null;
      stored.wordCourse.ruleLessonsHeard[focusId] = true;
      saveStored();
      setMicState('ready');
      return;
    }
    const stepIndex = playback.stepIndex++;
    const step = steps[stepIndex];
    const ownsStep = () => ownsLesson() && playback.stepIndex === stepIndex + 1;
    if (step.kind === 'speech') {
      const speakingRate = step.rate === undefined ? 0.9 : step.rate;
      const pauseAfterSpeechMs = step.pauseAfterMs === undefined ? 0 : step.pauseAfterMs;
      if (!Number.isFinite(speakingRate) || speakingRate <= 0 ||
          !Number.isFinite(pauseAfterSpeechMs) || pauseAfterSpeechMs < 0) {
        failLesson('The rule has invalid speech pacing.');
        return;
      }
      speak(step.text, speakingRate, how => {
        if (!ownsStep()) return;
        if (how !== 'onend') { failLesson('The spoken rule could not play.'); return; }
        if (pauseAfterSpeechMs === 0) { playNextStep(); return; }
        playback.speechPauseTimer = setTimeout(() => {
          if (ownsStep()) playNextStep();
        }, pauseAfterSpeechMs);
      }, { ruleLessonPlayback:playback });
      return;
    }
    const audio = new Audio('./audio/letters/' + step.clipKey + '.mp3?v=' + AUDIO_VERSION);
    playback.audio = audio;
    audio.onended = () => { if (ownsStep()) playNextStep(); };
    audio.onerror = () => { if (ownsStep()) failLesson('The recorded rule sound could not play.'); };
    playback.soundDeadlineTimer = setTimeout(() => {
      if (ownsStep()) failLesson('The recorded rule sound took too long to play.');
    }, 10000);
    try {
      audio.play().catch(() => {
        if (ownsStep()) failLesson('The recorded rule sound could not play.');
      });
    } catch (_) { failLesson('The recorded rule sound could not play.'); }
  };
  playNextStep();
}

// Only focus encounters show the current level's one teaching rule.
// Familiar words retain sound buttons without introducing another rule.
function renderRuleChips(item) {
  const host = document.getElementById('rule-chips');
  host.innerHTML = '';
  const hasFocus = gs.currentSet === 'words' && gs.currentEncounterRole === 'focus';
  host.classList.toggle('hidden', !hasFocus);
  if (!hasFocus) return;
  const focus = wordCourseLevel(gs.currentLevel);
  if (!focus.focusWordIds.includes(item.id)) throw new Error('The displayed focus word is outside its level.');
  const chip = document.createElement('button');
  chip.className = 'rule-chip';
  chip.style.setProperty('--chip', '#4fc3f7');
  const label = document.createElement('span');
  label.className = 'rule-chip-label';
  label.textContent = focus.focus;
  const icon = document.createElement('span');
  icon.className = 'rule-chip-icon';
  icon.setAttribute('aria-hidden', 'true');
  icon.textContent = '🔊';
  chip.append(label, icon);
  chip.setAttribute('aria-label', 'Hear the rule: ' + focus.focus);
  chip.addEventListener('click', () => {
    if (gs.currentItem !== item || gs.spokenWordEncounter?.phase !== 'first-ready' ||
        (micState !== 'ready' && activeRuleLessonPlayback?.encounter !== gs.spokenWordEncounter)) return;
    startRuleLessonPlayback(focus.id, item);
  });
  host.appendChild(chip);
}

function beginWordEncounter(item) {
  cancelWordEncounter();
  gs.spokenWordEncounter = {
    sequence: ++spokenWordEncounterSequence,
    itemId: item.id,
    phase: 'first-ready',
    firstAttemptAssistance: null,
    answerPlaybackSequence: 0,
    answerChoiceActivationTimer: null,
    committed: false,
  };
}

function cancelWordEncounter() {
  cancelRuleLessonPlayback('word or screen changed');
  stopLetterSoundPlayback();
  spokenWordEncounterSequence++;
  spokenAttemptGeneration++;
  clearTimeout(maxListenTimer);
  cancelUnblock();
  clearTimeout(gs.spokenWordEncounter?.answerChoiceActivationTimer);
  gs.spokenWordEncounter = null;
  gs.awaitingResult = false;
}

function confirmFirstSpokenAttempt() {
  if (micState !== 'confirming' || gs.spokenWordEncounter?.phase !== 'confirming') return;
  commitSelfCheckedAnswer('confirmed-first');
}

function commitSelfCheckedAnswer(outcome) {
  const encounter = gs.spokenWordEncounter;
  if (!encounter || encounter.committed) return;
  const helpedRepeat = outcome === 'helped-repeat';
  if (outcome !== 'confirmed-first' && !helpedRepeat) throw new Error('Unknown self-check outcome.');
  if (encounter.phase !== (helpedRepeat ? 'repeat-recorded' : 'confirming')) return;
  const assistance = encounter.firstAttemptAssistance;
  if (!assistance || encounter.itemId !== gs.currentItem?.id) throw new Error('The self-check must belong to its recorded word.');
  encounter.committed = true;
  encounter.phase = 'completed';
  clearTimeout(encounter.answerChoiceActivationTimer);
  encounter.answerChoiceActivationTimer = null;
  if (!helpedRepeat) speechSynthesis.cancel();
  gs.awaitingResult = true;
  setMicState('waiting');
  const item = gs.currentItem;
  const finishFeedback = () => {
    if (gs.spokenWordEncounter !== encounter || !encounter.committed) return;
    gs.awaitingResult = false;
    nextItem();
  };
  // Recaps remain feedback-only: neither capture nor confirmation changes
  // attempts, trophies, confirmation counts, round score or level progress.
  if (item.id === gs.recapId) {
    playPling();
    speak(helpedRepeat ? 'Nice practice!' : 'Well done!', 1.05, finishFeedback);
    return;
  }
  item.totalAttempts += helpedRepeat ? 2 : 1;
  item.totalCorrect++;
  if (helpedRepeat) {
    item.successStreak = 0;
    item.unaidedStreak = 0;
    if (gs.currentEncounterRole === 'focus') gs.ruleMissed = true;
  }
  item.successStreak++;
  item.lastResult = helpedRepeat ? 'helped' : 'correct';

  const firstTry = !helpedRepeat && !assistance.hearPressed;
  if (firstTry) {
    item.unaidedStreak++;
    item.silentCorrect++;
    gs.roundSilentCorrect++;
  }

  // The assistance snapshot belongs to the submitted first answer.
  // Hearing the automatic comparison afterward cannot change eligibility.
  // Gold/purple each require two qualifying first-attempt Yeses. A helped
  // repeat preserves earlier confirmations and cannot add another one.
  let newTrophy = null;
  if (firstTry) {
    if (assistance.letterTaps >= 2 && !item.decoded) { item.decoded = true; newTrophy = 'silver'; }
    if (assistance.letterTaps <= 1) {
      item.masteryConfirmationCount = Math.min(2, item.masteryConfirmationCount + 1);
      if (item.masteryConfirmationCount === 2 && !item.mastered) { item.mastered = true; newTrophy = 'gold'; }
    }
    if (assistance.letterTaps === 0) {
      item.flawlessConfirmationCount = Math.min(2, item.flawlessConfirmationCount + 1);
      if (item.flawlessConfirmationCount === 2 && !item.flawless) { item.flawless = true; newTrophy = 'purple'; }
    }
  }

  gs.roundCorrect++;
  gs.completedCount++;
  saveStored();
  flashScreen(true);
  renderConfirmationProgress(item);

  if (newTrophy) {
    gs.newTrophies++;
    renderTrophyRow(item, newTrophy);
    playTrophyChime(newTrophy);
    burstStars(70, TROPHY_PALETTES[newTrophy]);
    const praise = PRAISE[Math.random() * PRAISE.length | 0];
    // "red" is deliberate: spoken-only text, and the TTS reads "read" as
    // present-tense /reed/ where past-tense /red/ is meant.
    const line =
      newTrophy === 'purple' ? `Excellent! You red ${item.display} without any help!` :
      newTrophy === 'gold'   ? `${praise} You know ${item.display} now!` :
                               `${praise} You sounded it out!`;
    // Let the trophy arpeggio ring before the voice comes in.
    setTimeout(() => {
      if (gs.spokenWordEncounter !== encounter || !encounter.committed) return;
      speak(line, 1.05, finishFeedback);
    }, 800);
  } else {
    playPling();
    burstStars();
    speak(helpedRepeat ? 'Nice practice!' : PRAISE[Math.random() * PRAISE.length | 0], 1.05, finishFeedback);
  }
  renderDots();
}

function endRound() {
  stored.rounds.push({
    id:      new Date().toISOString(),
    set:     gs.currentSet,
    level:   gs.currentLevel,
    courseId: gs.currentSet === 'words' ? WORD_COURSE.id : 'number-course-1-to-100',
    endedAt: new Date().toISOString(),
    correct: gs.roundCorrect,
    total:   gs.completedCount,
  });
  saveStored();
  closeMicStream();

  const levelKey   = gs.currentSet === 'numbers' ? 'numberLevel' : 'wordLevel';
  const wasOnCurrent = gs.currentLevel === stored.settings[levelKey];
  const levelResult = wasOnCurrent ? checkLevelComplete() : null;
  showAllDone(levelResult);
}

function checkLevelComplete() {
  const level = gs.currentLevel;
  if (gs.currentSet === 'words') {
    if (!wordCourseFocusComplete(level)) return null;
    let nextLevel = level + 1;
    while (nextLevel <= WORD_COURSE.levels.length && wordCourseFocusComplete(nextLevel)) nextLevel++;
    if (nextLevel > WORD_COURSE.levels.length) {
      return WORD_COURSE.levels.every(focus => wordCourseFocusComplete(focus.level)) ? 'all_defeated' : null;
    }
    stored.settings.wordLevel = nextLevel;
  } else {
    const items = Object.values(stored.items).filter(item => item.kind === 'number' && item.level === level);
    if (!items.length || !items.every(item => item.mastered)) return null;
    if (level >= NUMBER_LEVEL_COUNT) return 'all_defeated';
    stored.settings.numberLevel = level + 1;
  }
  saveStored();
  return 'level_complete';
}

// ============================================================
// CAPTURE RECOVERY
// ============================================================

function recoverSpokenCapture(message) {
  const encounter = gs.spokenWordEncounter;
  closeMicStream();
  if (!encounter || encounter.committed) return;
  const helpedRepeat = encounter.phase === 'repeat-recording' || encounter.phase === 'repeat-ready' || encounter.phase === 'repeat-recorded';
  encounter.phase = helpedRepeat ? 'repeat-ready' : 'first-ready';
  setMicState(helpedRepeat ? 'repeat-ready' : 'ready');
  document.getElementById('mic-status').textContent = message;
  speak(message, 0.9);
}

function onMicDenied() {
  sessionMicBlocked = true;
  if (auditionState !== 'idle') {
    failAuditionRecording('Microphone access was not allowed.');
    return;
  }
  recoverSpokenCapture('Microphone not available. Please allow microphone access and try again.');
}

function onMicUnavailable() {
  if (auditionState !== 'idle') {
    failAuditionRecording('Microphone could not start.');
    return;
  }
  recoverSpokenCapture('Microphone could not start. Reload the app and try again.');
}

function failAuditionRecording(message) {
  const tuningRowId = auditionState !== 'idle' ? auditionRowId : null;
  closeMicStream();
  auditionState = 'idle';
  auditionRowId = null;
  if (tuningRowId) {
    setRowListening(tuningRowId, false);
    setRowResult(tuningRowId, 'miss', message);
  }
}

function onSpeechEngineError(error) {
  DBG('speech engine could not check tuning recording', error);
  failAuditionRecording('Speech engine could not check recording: ' + String(error));
}

// ============================================================
// UI
// ============================================================

let currentlyDisplayedScreenSequence = 0;
let currentlyDisplayedScreenName = 'loading';

function showScreen(name) {
  currentlyDisplayedScreenSequence++;
  currentlyDisplayedScreenName = name;
  if (name !== 'practice') {
    cancelWordEncounter();
    closeMicStream();
  }
  document.querySelectorAll('.screen').forEach(el =>
    el.classList.toggle('hidden', el.id !== 'screen-' + name)
  );
}

// A microphone startup deadline reports an unscored capture error. It cannot
// reset a completed first answer or erase a pending helped repeat.
function armUnblock(ms) {
  clearTimeout(unblockTimer);
  const attemptGeneration = spokenAttemptGeneration;
  unblockTimer = setTimeout(() => {
    if (attemptGeneration !== spokenAttemptGeneration) return;
    if (micState !== 'warming') return;
    recoverSpokenCapture('The microphone took too long to start. Please try again.');
  }, ms);
}
function cancelUnblock() { clearTimeout(unblockTimer); }

function setMicState(state) {
  DBG('micState', `${micState} -> ${state}`);
  micState = state;
  // Arm a hard deadline whenever we enter a non-interactive state.
  if (state === 'warming') armUnblock(14000);
  else cancelUnblock();
  const btn     = document.getElementById('mic-button');
  const lbl     = document.getElementById('mic-status');
  const hearBtn = document.getElementById('hear-button');
  const yesBtn = document.getElementById('self-check-yes');
  const question = document.getElementById('self-check-question');
  const encounter = gs.spokenWordEncounter;
  const comparing = encounter?.phase === 'answer' || encounter?.phase === 'confirming';
  const playbackError = encounter?.phase === 'answer-error';
  if (yesBtn) {
    yesBtn.classList.toggle('hidden', !comparing);
    yesBtn.disabled = state !== 'confirming';
  }
  if (question) question.classList.toggle('hidden', !comparing && !playbackError);
  if (hearBtn) {
    hearBtn.classList.toggle('hidden', Boolean(encounter && encounter.phase !== 'first-ready' && encounter.phase !== 'first-recording' && !playbackError));
    hearBtn.disabled = state !== 'ready' && !playbackError && activeRuleLessonPlayback?.encounter !== encounter;
    hearBtn.classList.toggle('disabled', hearBtn.disabled);
  }
  // Pointer release must still reach the mic while permission/resume is
  // warming; disabling it there can strand a cancelled hold in real browsers.
  btn.disabled = state === 'waiting' || playbackError;
  btn.setAttribute('aria-label', state === 'confirming' || state === 'repeat-ready' ? 'Record the word again' : 'Say the word');
  btn.classList.remove('listening', 'waiting', 'warming');
  if (state === 'warming') {
    btn.classList.add('warming');
    lbl.textContent = 'Get ready…';
  } else if (state === 'listening') {
    btn.classList.add('listening');
    lbl.textContent = 'Speak now!';
  } else if (state === 'waiting') {
    btn.classList.add('waiting');
    lbl.textContent = '';
  } else if (state === 'confirming' || state === 'repeat-ready') {
    lbl.textContent = 'Say it again';
  } else {
    lbl.textContent = 'Hold and speak';
  }
}

function playPling() {
  try {
    const ctx = new (window.AudioContext || window.webkitAudioContext)();
    const t = ctx.currentTime;
    // C major chord upper register: C6, E6, G6
    [[1046.5, 0.3], [1318.5, 0.22], [1568.0, 0.14]].forEach(([freq, vol]) => {
      const osc  = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.type = 'sine';
      osc.frequency.setValueAtTime(freq, t);
      gain.gain.setValueAtTime(0, t);
      gain.gain.linearRampToValueAtTime(vol, t + 0.012);
      gain.gain.exponentialRampToValueAtTime(0.001, t + 0.48);
      osc.start(t);
      osc.stop(t + 0.55);
    });
    setTimeout(() => { try { ctx.close(); } catch (_) {} }, 700);
  } catch (_) {}
}

// ── Trophies ──
// silver: sounded the word out with letter taps (>=2 taps, no Hear it)
// gold:   read it with at most one tap (mastery — word leaves the rotation)
// purple: read it with no taps at all (flawless)
const TROPHY_DEFS = [
  ['decoded',  'silver', 'Sounded it out'],
  ['mastered', 'gold',   'Knows it'],
  ['flawless', 'purple', 'Read it without help'],
];

const TROPHY_PALETTES = {
  silver: ['#e6edf5', '#aebfd4', '#8fb8ff', '#ffffff', '#c0d8f0'],
  gold:   ['#ffd166', '#ffbe0b', '#ff9f1c', '#fff3c4', '#f9c74f'],
  purple: ['#b266ff', '#d29bff', '#8338ec', '#f0c4ff', '#ff66ff'],
};

// Rising arpeggios per trophy tier (the regular pling stays for plain praise).
const TROPHY_NOTES = {
  silver: [[659.25, 0], [987.77, 0.11]],
  gold:   [[523.25, 0], [659.25, 0.09], [784.0, 0.18], [1046.5, 0.27]],
  purple: [[523.25, 0], [659.25, 0.08], [784.0, 0.16], [1046.5, 0.24], [1318.5, 0.32]],
};

function playTrophyChime(tier) {
  try {
    const ctx = new (window.AudioContext || window.webkitAudioContext)();
    const t = ctx.currentTime;
    for (const [freq, dt] of TROPHY_NOTES[tier]) {
      const osc  = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.type = 'sine';
      osc.frequency.setValueAtTime(freq, t + dt);
      gain.gain.setValueAtTime(0, t + dt);
      gain.gain.linearRampToValueAtTime(0.25, t + dt + 0.015);
      gain.gain.exponentialRampToValueAtTime(0.001, t + dt + 0.6);
      osc.start(t + dt);
      osc.stop(t + dt + 0.7);
    }
    setTimeout(() => { try { ctx.close(); } catch (_) {} }, 1400);
  } catch (_) {}
}

// Show the word's earned trophies above it; `popTier` animates a fresh one.
function renderTrophyRow(item, popTier) {
  const el = document.getElementById('trophy-row');
  if (!el) return;
  el.innerHTML = '';
  if (!item) return;
  for (const [flag, tier, label] of TROPHY_DEFS) {
    if (!item[flag]) continue;
    const s = document.createElement('span');
    s.className   = 'trophy ' + tier + (tier === popTier ? ' pop' : '');
    s.textContent = '★';
    s.title       = label;
    el.appendChild(s);
  }
}

function renderConfirmationProgress(item) {
  const el = document.getElementById('confirmation-progress');
  if (!el) return;
  el.classList.toggle('hidden', !item || item.mastered || item.id === gs.recapId);
  el.innerHTML = '';
  if (!item || item.mastered || item.id === gs.recapId) return;
  el.setAttribute('aria-label', `${item.masteryConfirmationCount} of 2 confirmations`);
  for (let confirmation = 0; confirmation < 2; confirmation++) {
    const dot = document.createElement('span');
    dot.className = 'confirmation-dot' + (confirmation < item.masteryConfirmationCount ? ' filled' : '');
    dot.setAttribute('aria-hidden', 'true');
    el.appendChild(dot);
  }
}

function burstStars(count = 40, palette = null) {
  const wordEl = document.getElementById('word-display');
  if (!wordEl) return;
  const rect = wordEl.getBoundingClientRect();
  const cx = rect.left + rect.width  / 2;
  const cy = rect.top  + rect.height / 2;

  const canvas = document.createElement('canvas');
  canvas.width  = window.innerWidth;
  canvas.height = window.innerHeight;
  canvas.style.cssText = 'position:fixed;inset:0;pointer-events:none;z-index:999';
  document.body.appendChild(canvas);
  const c = canvas.getContext('2d');

  const COLORS   = palette || ['#ff6b6b','#ffd166','#06d6a0','#a78bfa','#ff9f1c','#4cc9f0','#f72585','#80ffdb','#ffbe0b'];
  const GRAVITY  = 0.22;
  const DURATION = 1800;

  const particles = Array.from({length: count}, () => {
    const angle = Math.random() * Math.PI * 2;
    const speed = 3 + Math.random() * 9;
    return {
      x:        cx + (Math.random() - 0.5) * rect.width  * 0.5,
      y:        cy + (Math.random() - 0.5) * rect.height * 0.3,
      vx:       Math.cos(angle) * speed,
      vy:       Math.sin(angle) * speed - 5,
      size:     8 + Math.random() * 14,
      color:    COLORS[Math.floor(Math.random() * COLORS.length)],
      rot:      Math.random() * Math.PI * 2,
      rotSpeed: (Math.random() - 0.5) * 0.28,
      isStar:   Math.random() < 0.6,
    };
  });

  function drawStar(x, y, r, rot) {
    const inner = r * 0.42;
    c.beginPath();
    for (let i = 0; i < 10; i++) {
      const a  = rot + (i * Math.PI) / 5;
      const ri = i % 2 === 0 ? r : inner;
      if (i === 0) c.moveTo(x + ri * Math.cos(a), y + ri * Math.sin(a));
      else         c.lineTo(x + ri * Math.cos(a), y + ri * Math.sin(a));
    }
    c.closePath();
  }

  const start = performance.now();
  (function tick(now) {
    const t = (now - start) / DURATION;
    if (t >= 1) { canvas.remove(); return; }
    c.clearRect(0, 0, canvas.width, canvas.height);
    c.globalAlpha = Math.max(0, 1 - t * 1.1);
    for (const p of particles) {
      p.x  += p.vx;
      p.y  += p.vy;
      p.vy += GRAVITY;
      p.rot += p.rotSpeed;
      c.fillStyle = p.color;
      if (p.isStar) { drawStar(p.x, p.y, p.size / 2, p.rot); }
      else          { c.beginPath(); c.arc(p.x, p.y, p.size / 2, 0, Math.PI * 2); }
      c.fill();
    }
    c.globalAlpha = 1;
    requestAnimationFrame(tick);
  })(start);
}

let flashTimer = null;
function flashScreen(correct) {
  const el = document.getElementById('flash-overlay');
  if (!el) return;
  el.className = 'flash-overlay ' + (correct ? 'correct' : 'incorrect') + ' show';
  clearTimeout(flashTimer);
  flashTimer = setTimeout(() => { el.className = 'flash-overlay'; }, 400);
}

function renderDots() {
  const el = document.getElementById('round-progress');
  if (!el) return;
  const total = gs.originalSize;
  const done  = gs.completedCount;
  const cur   = Math.min(done, total - 1);

  el.innerHTML = '';
  for (let i = 0; i < total; i++) {
    const d = document.createElement('div');
    d.className = 'progress-dot' + (i < done ? ' done' : i === cur && !gs.awaitingResult ? ' current' : '');
    el.appendChild(d);
  }
}

// Spoken at round end when the rule block was cleared without a miss:
// credit for the insight, not just the utterances.
function rulePraise() {
  if (gs.currentSet !== 'words' || gs.ruleMissed) return '';
  return ' You practised words like ' + wordCourseLevel(gs.currentLevel).focusWords[0] + '!';
}

function showAllDone(levelResult) {
  if (levelResult) {
    showLevelUp(levelResult);
    return;
  }

  showScreen('alldone');
  const total  = gs.originalSize;
  const silent = gs.roundSilentCorrect;
  const noun   = gs.currentSet === 'numbers' ? 'number' : 'word';
  const stars  = Math.max(1, Math.round(
    (silent > 0 ? silent : gs.roundCorrect) / Math.max(total, 1) * 5
  ));

  document.getElementById('alldone-title').textContent = `You practised ${total} ${noun}${total !== 1 ? 's' : ''}`;

  let scoreText, speakText;
  if (silent >= total && total > 0) {
    scoreText = 'Read them all by yourself!';
    // "red": spoken-only past-tense fix for the TTS heteronym.
    speakText = `You practised ${total} ${noun}s, and red them all by yourself.` + rulePraise() + ' See you again tomorrow!';
  } else if (silent > 0) {
    scoreText = `Got ${silent} right without hearing!`;
    speakText = `You practised ${total} ${noun}s, and got ${silent} right without hearing them first.` + rulePraise() + ' See you again tomorrow!';
  } else {
    scoreText = "You're learning — keep it up!";
    speakText = `You practised ${total} ${noun}s today.` + rulePraise() + ' See you again tomorrow!';
  }

  if (gs.newTrophies > 0) {
    const n = gs.newTrophies;
    scoreText += ` ★ ${n} new troph${n === 1 ? 'y' : 'ies'}!`;
    speakText = speakText.replace('See you again tomorrow!',
      `You won ${n} new troph${n === 1 ? 'y' : 'ies'}! See you again tomorrow!`);
  }

  document.getElementById('alldone-score').textContent = scoreText;
  const allDoneScreenSequence = currentlyDisplayedScreenSequence;
  setTimeout(() => {
    if (currentlyDisplayedScreenSequence !== allDoneScreenSequence || currentlyDisplayedScreenName !== 'alldone') return;
    speak(speakText, 0.85);
  }, 600);
}

function showLevelUp(result) {
  showScreen('levelup');
  const set    = gs.currentSet;
  const level  = gs.currentLevel;
  const isMax  = result === 'all_defeated';
  const newLevel = isMax ? level : stored.settings[set === 'words' ? 'wordLevel' : 'numberLevel'];

  if (isMax) {
    document.getElementById('levelup-title').textContent = '🏆 Champion!';
    document.getElementById('levelup-body').textContent  =
      `You've conquered all ${levelCountForSet(gs.currentSet)} levels of ${set}! Keep practising to stay sharp!`;
    speak(`Champion! You have conquered all ${levelCountForSet(gs.currentSet)} levels of ${set}! You are amazing!`, 1.0);
  } else {
    document.getElementById('levelup-title').textContent = `🎉 Level ${level} complete!`;
    document.getElementById('levelup-body').textContent  =
      `Brilliant! You've unlocked Level ${newLevel} of ${set}!`;
    speak(`Level ${level} complete! You unlocked level ${newLevel}! Well done!` + rulePraise(), 1.0);
  }
  setLevelBackground(isMax ? level : newLevel, gs.currentSet);
}

